import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BHcoJYMQ.js";const m=JSON.parse('{"title":"Competitor profile template","description":"","frontmatter":{},"headers":[],"relativePath":"competitors/template.md","filePath":"competitors/template.md","lastUpdated":1794243308000}'),i={name:"competitors/template.md"};function o(n,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="competitor-profile-template" tabindex="-1">Competitor profile template <a class="header-anchor" href="#competitor-profile-template" aria-label="Permalink to &quot;Competitor profile template&quot;">​</a></h1><p>Copy this page for each brand. Keep it concise, link sources beside factual claims, and use <strong>Unknown</strong> where evidence is missing.</p><p><strong>Website:</strong> — · <strong>Type:</strong> — · <strong>Market:</strong> — · <strong>Last reviewed:</strong> YYYY-MM-DD</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Who is the customer? What does the brand promise? What makes it different? Summarize in two or three sentences, including whether its current range is focused on one product.</p><h2 id="product-price" tabindex="-1">Product &amp; price <a class="header-anchor" href="#product-price" aria-label="Permalink to &quot;Product &amp; price&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Reference white T-shirt</th><th>Details</th></tr></thead><tbody><tr><td>Product / link</td><td>—</td></tr><tr><td>Fabric / weight / fit / sizes</td><td>—</td></tr><tr><td>Price / currency / pack size</td><td>—</td></tr><tr><td>Shipping / returns</td><td>—</td></tr></tbody></table><p>Record the exact white variant, date, and region. Separate regular and sale prices; calculate per-shirt pricing for packs. Label product-performance statements as brand claims unless independently tested.</p><h2 id="brand-website" tabindex="-1">Brand &amp; website <a class="header-anchor" href="#brand-website" aria-label="Permalink to &quot;Brand &amp; website&quot;">​</a></h2><ul><li><strong>Messaging:</strong> main promise and supporting proof.</li><li><strong>Visual style:</strong> typography, color, photography, and layout.</li><li><strong>Shopping experience:</strong> discovery, product page, and buying friction.</li><li><strong>Persuasion &amp; archetypes:</strong> observed examples and tentative interpretations. Link evidence; don’t assume the brand intended a particular framework.</li></ul><h2 id="customer-evidence" tabindex="-1">Customer evidence <a class="header-anchor" href="#customer-evidence" aria-label="Permalink to &quot;Customer evidence&quot;">​</a></h2><p>What do customers repeatedly praise or criticize? Link the review sources, note the sample size and dates, and identify limitations. A few selected reviews do not represent all customers.</p><h2 id="takeaways" tabindex="-1">Takeaways <a class="header-anchor" href="#takeaways" aria-label="Permalink to &quot;Takeaways&quot;">​</a></h2><ul><li><strong>What we learned:</strong> evidence-backed strengths, weaknesses, or patterns.</li><li><strong>What we might test:</strong> an idea for our project, clearly marked as a hypothesis.</li><li><strong>Still unknown:</strong> the most important gap or next question.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>Keep URLs beside claims. Use this section for any additional source notes, access dates, and conflicting evidence. Prefer official pages for product facts and policies; use independent evidence to assess performance and customer experience.</p>',16)])])}const u=t(i,[["render",o]]);export{m as __pageData,u as default};
